using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class RoomStub
{
	public string name;

	public RoomType type;

	public int width;

	public int height;

	public ElementType element;

	public MapDirections optionalConnections;

	public MapDirections requiredConnections;

	private static WaitForFixedUpdate fixedWait = new WaitForFixedUpdate();

	public MapDirections AllowedConnections => optionalConnections | requiredConnections;

	public RoomStub(RoomType newType)
	{
		type = newType;
	}

	public RoomStub(RoomStub stub)
	{
		name = stub.name;
		type = stub.type;
		width = stub.width;
		height = stub.height;
		element = stub.element;
		optionalConnections = stub.optionalConnections;
		requiredConnections = stub.requiredConnections;
	}

	public RoomStub(Room room)
	{
		name = room.name;
		type = room.type;
		width = room.Width;
		height = room.Height;
		element = room.element;
		optionalConnections = room.optionalConnections;
		requiredConnections = room.requiredConnections;
	}

	public static List<RoomStub> LoadAll()
	{
		List<RoomStub> list = new List<RoomStub>();
		string assetPath = "Assets/Data/Rooms/RoomDB.json";
		string text = ChaosBundle.Get<TextAsset>(assetPath).text;
		int num = 0;
		for (int num2 = text.IndexOf("!=-=!"); num2 >= 0; num2 = text.IndexOf("!=-=!", num))
		{
			RoomStub item = JsonUtility.FromJson<RoomStub>(text.Substring(num, num2 - num));
			list.Add(item);
			num = num2 + 5;
		}
		return list;
	}

	public static IEnumerator LoadAll(List<RoomStub> givenList)
	{
		string jsonPath = "Assets/Data/Rooms/RoomDB.json";
		string roomDB = ChaosBundle.Get<TextAsset>(jsonPath).text;
		string endIndexStr = "!=-=!";
		int startIndex = 0;
		int endIndex = roomDB.IndexOf(endIndexStr);
		while (endIndex >= 0)
		{
			givenList.Add(JsonUtility.FromJson<RoomStub>(roomDB.Substring(startIndex, endIndex - startIndex)));
			startIndex = endIndex + 5;
			endIndex = roomDB.IndexOf(endIndexStr, startIndex);
			yield return fixedWait;
		}
	}
}
public enum RoomType
{
	Standard,
	Survival,
	Challenge,
	Treasure,
	Start,
	Exit,
	ItemStore,
	SkillStore,
	RandomSurvival,
	FloorPlan,
	Hallway,
	End,
	Misc,
	Party
}
using System.Collections;
using UnityEngine;

public class LevelGenerator
{
	public delegate void LevelGeneratedEventHandler();

	private static EnemyDecorator _enemyDecorator;

	private static float failsafeTime = 10f;

	private static float lastLoadTime;

	public static LevelGeneratedEventHandler levelGeneratedEventHandlers;

	private static int loadingScreenMsgIndex;

	private static string loadingScreenMsgBase = "<color=#333333>";

	private static string loadingScreenMsgInactive = string.Empty;

	private static string loadingScreenMsgActive = string.Empty;

	public static EnemyDecorator EnemyDecorator
	{
		get
		{
			if (_enemyDecorator == null)
			{
				_enemyDecorator = new EnemyDecorator();
			}
			return _enemyDecorator;
		}
	}

	public static void UpdateLastLoadTime()
	{
		lastLoadTime = Time.time - lastLoadTime;
		failsafeTime = failsafeTime * 0.8f + lastLoadTime * 0.2f;
	}

	public static IEnumerator Generate(MonoBehaviour inst, int width = 512, int height = 512)
	{
		EnemyDecorator.InitializeDecorator();
		Level.prevElement = Level.element;
		bool layoutGeneratorStarted = false;
		bool layoutGeneratorComplete = false;
		string sceneName = Application.loadedLevelName;
		GameController.loadingScreen.SetPromptText(string.Empty);
		GameController.pauseTimer = true;
		loadingScreenMsgInactive = loadingScreenMsgBase;
		loadingScreenMsgActive = string.Empty;
		loadingScreenMsgIndex = 0;
		UpdateLoadingScreenMessage();
		yield return null;
		int levelStopwatchID = -1;
		while (!layoutGeneratorComplete)
		{
			if (LayoutGenerator.forceQuitGenerate)
			{
				if (LayoutGenerator.isGenerating)
				{
					yield return null;
				}
				LayoutGenerator.forceQuitGenerate = false;
				Debug.Log("Error creating floor. Retrying...");
				if (Level.levelContainer != null && Level.levelContainer.gameObject != null)
				{
					Object.Destroy(Level.levelContainer.gameObject);
				}
				LayoutGenerator.ClearLists();
				layoutGeneratorStarted = false;
				layoutGeneratorComplete = false;
				GameController.loadingScreen.SetPromptText(string.Empty);
				loadingScreenMsgInactive = loadingScreenMsgBase;
				loadingScreenMsgActive = string.Empty;
				loadingScreenMsgIndex = 0;
				UpdateLoadingScreenMessage();
				yield return null;
			}
			if (!layoutGeneratorStarted)
			{
				Level.levelContainer = new GameObject("LevelContainer").transform;
				Level.tileGrid = new TileGrid(width, height);
				Level.totalEnemyCount = 0;
				Level.enemiesDefeatedCount = 0;
				Level.totalEnemyCount = 0;
				Level.enemiesDefeatedCount = 0;
				LayoutGenerator.StartGenerator(inst, Level.tileGrid);
				layoutGeneratorStarted = true;
				levelStopwatchID = ChaosStopwatch.Begin(failsafeTime * 1.75f);
				lastLoadTime = Time.time;
			}
			else if (!LayoutGenerator.isGenerating)
			{
				layoutGeneratorComplete = true;
			}
			else if (!LayoutGenerator.ConnectionsExist || ChaosStopwatch.Check(levelStopwatchID))
			{
				if (Level.levelContainer != null && Level.levelContainer.gameObject != null)
				{
					Object.Destroy(Level.levelContainer.gameObject);
				}
				LayoutGenerator.forceQuitGenerate = true;
				UpdateLastLoadTime();
			}
			if (!LayoutGenerator.forceQuitGenerate && sceneName != Application.loadedLevelName)
			{
				LayoutGenerator.forceQuitGenerate = true;
				yield break;
			}
			yield return null;
		}
		UpdateLastLoadTime();
		UpdateLoadingScreenMessage();
		yield return null;
		Level.tileGrid.FinalizeTerrain();
		UpdateLoadingScreenMessage();
		inst.StartCoroutine(OverlayGenerator.GenerateOverlay(Level.tileGrid, 8));
		while (OverlayGenerator.overlayGenerationInProgress)
		{
			yield return null;
		}
		UpdateLoadingScreenMessage();
		yield return null;
		DecorationApplier.ApplyAllDecorations(Level.levelContainer.transform, Level.tileGrid);
		yield return null;
		OrganicPathGenerator.GenerateOrganicPaths(Level.tileGrid, TileSet.Factory(Level.tileSetName));
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		Decorator.DecorateByTileSet(Level.tileSetName, Level.tileGrid, DecorationMode.Global);
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		EnemyDecorator.DecorateTupleList(Level.GridRoomTupleList);
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		for (int i = 0; i < Level.GridRoomTupleList.Count; i++)
		{
			Room second = Level.GridRoomTupleList[i].Second;
			if (second.randomInteractables || second.type == RoomType.FloorPlan)
			{
				Decorator.DecorateByTileSet(Level.tileSetName, Level.GridRoomTupleList[i].First, DecorationMode.Room, second);
			}
		}
		yield return null;
		HallwayDecorator.DecorateByTileSet(Level.tileSetName, Level.GridHallTupleList);
		yield return null;
		Decorator.DecorateByTileSet(Level.tileSetName, Level.tileGrid, DecorationMode.Global, null, 1);
		yield return null;
		Decoration.ClearGlobalPositions();
		yield return null;
		UpdateLoadingScreenMessage();
		yield return null;
		Level.tileGrid.InitLayerVertices(forceVertexUpdate: true, string.Empty);
		yield return null;
		WallGenerator.GenerateWalls(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		MeshGenerator.GenerateMeshes(Level.tileGrid, Level.levelContainer.transform, string.Empty);
		yield return null;
		PitGenerator.GeneratePits(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		CheckpointGenerator.GenerateCheckpoints(Level.tileGrid, Level.levelContainer.transform);
		yield return null;
		SetMinMaxPositions();
		yield return null;
		GameController.minimap.InitStageVars(Level.tileGrid);
		yield return null;
		inst.StartCoroutine(Pathfinder.GenerateNodeMap(Level.tileGrid));
		yield return null;
		SetStartPosition();
		SetExitAndStorePositions();
		UpdateLoadingScreenMessage();
		yield return Globals.waitForOne;
		if (Level.isBossRushMode)
		{
			foreach (CompassIndicatorTrigger trigger in CompassIndicatorTrigger.Triggers)
			{
				trigger.Activate();
			}
			foreach (MinimapSection minimapSection in MinimapSection.MinimapSections)
			{
				minimapSection.Reveal(collidedWithPlayer: true);
			}
		}
		GameController.loadingScreen.SetPromptText(string.Empty);
		GameController.loadingScreen.FadeOut();
		GameController.pauseTimer = false;
		yield return null;
		if (levelGeneratedEventHandlers != null)
		{
			levelGeneratedEventHandlers();
		}
		yield return null;
	}

	public static void SetStartPosition()
	{
		Vector2 startPosition = Level.startPosition;
		Player[] playerScripts = GameController.playerScripts;
		foreach (Player player in playerScripts)
		{
			if (!(player == null))
			{
				player.transform.position = startPosition;
				player.myOrigin = startPosition;
				player.lastCheckpoint = player.myOrigin;
				player.facingDirection = FacingDirection.Down;
				player.anim.Play("IdleDown");
			}
		}
		Camera.main.transform.position = new Vector3(startPosition.x, startPosition.y, -10f);
	}

	public static void SetExitAndStorePositions()
	{
		foreach (Tuple<TileGridSection, Room> gridRoomTuple in Level.GridRoomTupleList)
		{
			Room second = gridRoomTuple.Second;
			switch (second.type)
			{
			case RoomType.Exit:
				Level.exitPosition = second.transform.Find("Enemies/ExitRoomEventHandler").position;
				break;
			case RoomType.ItemStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.itemStorePortalInPosition = transform.Find("Spawn").position;
				Level.itemStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.SkillStore:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.skillStorePortalInPosition = transform.Find("Spawn").position;
				Level.skillStorePortalOutPosition = transform.Find("Exit").position;
				break;
			}
			case RoomType.Misc:
			{
				Transform transform = second.transform.Find("Interactables/Portal");
				Level.miscRoomPortalInPosition = transform.Find("Spawn").position;
				Level.miscRoomPortalOutPosition = transform.Find("Exit").position;
				break;
			}
			}
		}
		Level.miscRoomFound = (Level.skillStoreFound = (Level.itemStoreFound = (Level.exitFound = Level.isBossRushMode)));
	}

	public static void SetMinMaxPositions()
	{
		TileGrid tileGrid = Level.tileGrid;
		int rowCount = Level.tileGrid.RowCount;
		int colCount = Level.tileGrid.ColCount;
		Vector2 vector = new Vector2((float)rowCount * 0.5f, (float)colCount * 0.5f);
		Vector2 vector2 = vector;
		for (int i = 0; i < rowCount; i++)
		{
			for (int j = 0; j < colCount; j++)
			{
				if (tileGrid[i, j] != null)
				{
					if ((float)i < vector.x)
					{
						vector.x = i;
					}
					else if ((float)i > vector2.x)
					{
						vector2.x = i;
					}
					if ((float)j < vector.y)
					{
						vector.y = j;
					}
					else if ((float)j > vector2.y)
					{
						vector2.y = j;
					}
				}
			}
		}
		Level.minTileGridPosition = new Vector2(vector.y, 0f - vector.x);
		Level.maxTileGridPosition = new Vector2(vector2.y, 0f - vector2.x);
	}

	private static void UpdateLoadingScreenMessage()
	{
		loadingScreenMsgInactive += loadingScreenMsgActive;
		loadingScreenMsgActive = "\n" + TextManager.GetUIText("loadingScreen-generation" + loadingScreenMsgIndex);
		loadingScreenMsgIndex++;
		GameController.loadingScreen.SetProgressText(loadingScreenMsgInactive + "</color>" + loadingScreenMsgActive + " ...");
	}
}
- **Реликвии без возвращения:** выпавшая вычёркивается из пула, повторов за забег нет. Проклятые — отдельный пул, 10%.
- **Невидимая подстройка наград:** собрал золота больше нормы — множитель падает до 0.5, меньше — растёт до 1.5. Чем меньше здоровья у слабейшего игрока — тем щедрее сердца. Игрок чувствует «справедливость», не видя переключателей.
- **Мета-прогрессия** растит не силу героя, а **разнообразие**: открытые заклинания и реликвии попадают в пул. Это и есть roguelite.

---

## 8. Уроки

**Сделано хорошо — брать:**
1. **Один FSM на всех.** Новое поведение = новое состояние, ядро не трогаем.
2. **Данные отдельно от кода.** Скиллы, лут, комнаты, диалоги (9 языков) — в JSON.
3. **Кулдаун гейтит эффект, а не движение.** Отзывчивость важнее «честной» блокировки.
4. **Парирование из существующего ввода.** Глубина без новой кнопки.
5. **Одна ручка сложности + бюджет комнаты.** Баланс крутится одним числом.
6. **Телеграфы и окна уязвимости.** Честность = игрок всегда может прочитать угрозу.
7. **Невидимая подстройка наград** и **сторож генератора**.

**Сделано плохо — не повторять:**
1. **God-классы.** `Player.cs` — ~29 000 строк в одном файле. Читать и тестировать невозможно.
2. **Строки вместо типов.** `ChangeState("Attack")`, имена сцен строками — опечатку найдёт только игрок.
3. **Глобальный рандом без сида.** Нет реплеев, нет воспроизводимых багов, нет автотестов.
4. **Часть чисел зашита в код** (шансы комнат, бюджеты врагов) — баланс только пересборкой.
5. **Нет буфера ввода** — для геймпада лучше 80–120 мс очереди нажатий.
6. **Фазы боссов флагами** `if (chaosMode)` по десяткам умений — каждая новая фаза умножает ветвления.

---

## 9. Цифры баланса (из данных игры)

Извлечено 659 файлов из бандла `core` (UnityPy). Баланс — JSON: `player/skills.json` (265 приёмов), `enemy/skills.json`, `loot/loottable.json` (80 строк), `loot/storeprices.json` (505 цен), `rooms/roomdb.json` (421 комната).

**Как устроен файл заклинаний.** Каждое поле — массив, индекс = удар серии или стадия приёма. Огненный удар: урон `[8, 8, 16]` — два обычных и сильный финал. Уровней прокачки в данных нет.

**Базовые атаки (урон по ударам серии):**

| Атака | Урон |
|---|---|
| Wind Slash | 8 → 10 → 12 → 14 (4 удара, растёт) |
| Flame Strike | 8 → 8 → 16 |
| Earth Knuckles | 16 → 18 → 20 (медленнее, тяжелее) |
| Chaos Crusher | 10 → 5 |

**Арканы — урон / кулдаун (с):**

| Аркана | Урон | КД | Особенность |
|---|---|---|---|
| Aqua Beam | 10 × тики | 0.75 | почти без КД, урон потоком |
| Star Bolt | 10 | 3.25 | |
| Mortal Coil | 25,25,10,50 | 3.5 | |
| Flame Cleaver | 14 | 4 | поджог 100% |
| Earthquake Axe | 10→50 (5 ударов) | 4.5 | |
| Frost Fan | 25 | 6 | заморозка 100% |
| Airborne Slam | 50 | 6 | замедление 100% |
| Toxic Bolas | 30 / 75 | 6 | яд + корни |
| Dragon Fall | 75 | 8 | |

Закономерность: **урон ≈ пропорционален кулдауну**, а статус (поджог, заморозка) стоит «дороже» сырого урона. Рывки: КД 3.5–6 с.

**Враги:** рыцарь 25 урона, разбойник 15 (но крит 25–35% ×2), голем 50 + оглушение 1.5 с, элитный рыцарь 75. Огненный босс: комбо 10/20/30 с откидыванием 25/25/75 — финальный удар серии всегда сильнее. Атак у боссов: финальный 16, огненный 9, остальные по 7. Здоровья врагов и длительности замахов в JSON нет — они в префабах.

**Дроп (вероятность на убийство):**

| Источник | Золото | Платина | Сердце | Прочее |
|---|---|---|---|---|
| Рыцарь | до 6 | 10% | 5% | |
| Лучник / разбойник | до 8 | 12% | 4% | реликвия 1% |
| Огненный рыцарь | до 10 | 50% | 7% | |
| Сундук | 30–50 | 5 | 25% | реликвия 10%, аркана 10% |
| Сундук мини-босса | 40–50 | 10 | 30% | реликвия 35% |
| Сундук босса | — | 20 | 30% | гарантированно аркана + новая аркана |
| Ящик/горшок | 5% по 2 | 0.5% | 0.3% | |

Стихийные враги платят больше платины — награда за сложность.

**Цены (платина):** базовые атаки и рывки 2, стихийные арканы 5–7, хаос-арканы 10–12, предметы обычно 6, сильные до 12.

**Комнаты:** 421 штука, ширина/высота 4–28 клеток, чаще всего 16×16, 12×12, 16×12. Основной фонд — 111 обычных боевых + 137 коридоров/проходов.

**Сверка с кодом.** Длительность рывка (0.125 с), формула шкалы ульты, шанс проклятия 10% и формула цен по тирам в JSON не встречаются — это константы, зашитые прямо в код (раздел 3 и 7), данные их не подтверждают и не опровергают. У шкалы ульты в данных есть поправочный множитель на каждый приём (`overdriveProgressMultiplier` 0–1): быстрые приёмы вроде Aqua Beam копят ульту в 4 раза медленнее.

---

