public static class LayoutGeneratorHelper
{
	private static Tile tempTile;

	private static int rowIter;

	private static int colIter;

	private static TileGrid adjGrid;

	private static Vector2 adjustedMax = Vector2.zero;

	private static Tile.ConnectionType originConnType;

	private static Tile.ConnectionType foundConnType;

	private static IntVec2 foundConnCoord = default;

	private static IntVec2 placeRoomMax;

	private static int placeRoomState;

	public static void GetAdjustedTileGrid(ref TileGrid givenGrid, RoomStub givenStub, ref Dictionary<IntVec2, Tile> givenConnectionDict, bool isRoom)
	{
		int num = 4;
		int num2 = 2;
		if (isRoom)
		{
			adjGrid = new TileGrid(givenGrid.RowCount + 2 * num, givenGrid.ColCount + 2 * num2);
			adjustedMax.x = adjGrid.RowCount - num;
			adjustedMax.y = adjGrid.ColCount - num2;
			for (rowIter = 0; rowIter < adjGrid.RowCount; rowIter++)
			{
				for (colIter = 0; colIter < adjGrid.ColCount; colIter++)
				{
					if (rowIter < num || colIter < num2 || (float)rowIter >= adjustedMax.x || (float)colIter >= adjustedMax.y)
					{
						adjGrid[rowIter, colIter] = new Tile(Tile.TerrainType.Impassable);
					}
					else
					{
						tempTile = givenGrid[rowIter - num, colIter - num2];
						if (tempTile == null)
						{
							adjGrid[rowIter, colIter] = new Tile(Tile.TerrainType.Impassable);
						}
						else
						{
							adjGrid[rowIter, colIter] = new Tile(tempTile);
							if (adjGrid[rowIter, colIter].connection != Tile.ConnectionType.None)
							{
								givenConnectionDict.Add(new IntVec2(rowIter, colIter), adjGrid[rowIter, colIter]);
							}
						}
					}
					adjGrid[rowIter, colIter].roomStub = givenStub;
				}
			}
			givenGrid = adjGrid;
			return;
		}
		for (rowIter = 0; rowIter < givenGrid.RowCount; rowIter++)
		{
			for (colIter = 0; colIter < givenGrid.ColCount; colIter++)
			{
				if (givenGrid[rowIter, colIter] != null)
				{
					if (givenGrid[rowIter, colIter].connection != Tile.ConnectionType.None)
					{
						givenConnectionDict.Add(new IntVec2(rowIter, colIter), givenGrid[rowIter, colIter]);
					}
					givenGrid[rowIter, colIter].roomStub = givenStub;
				}
			}
		}
	}

	public static void PaveConnectionPaths(ref TileGrid givenGrid, MapDirections givenDirection, ref Dictionary<IntVec2, Tile> givenConnectionDict, ref List<IntVec2> givenConnectionList)
	{
		List<IntVec2> list = new List<IntVec2>();
		switch (givenDirection)
		{
		case MapDirections.North:
			originConnType = Tile.ConnectionType.TopOptional;
			break;
		case MapDirections.South:
			originConnType = Tile.ConnectionType.BottomOptional;
			break;
		case MapDirections.East:
			originConnType = Tile.ConnectionType.RightOptional;
			break;
		case MapDirections.West:
			originConnType = Tile.ConnectionType.LeftOptional;
			break;
		default:
			originConnType = Tile.ConnectionType.None;
			break;
		}
		foreach (KeyValuePair<IntVec2, Tile> item2 in givenConnectionDict)
		{
			foundConnCoord = item2.Key;
			foundConnType = Tile.ConnectionType.None;
			if (item2.Value.connection == Tile.ConnectionType.TopOptional || item2.Value.connection == Tile.ConnectionType.TopRequired)
			{
				foundConnType = Tile.ConnectionType.TopOptional;
				for (int num = foundConnCoord.x - 1; num >= 0; num--)
				{
					givenGrid[num, foundConnCoord.y] = null;
				}
			}
			else if (item2.Value.connection == Tile.ConnectionType.BottomOptional || item2.Value.connection == Tile.ConnectionType.BottomRequired)
			{
				foundConnType = Tile.ConnectionType.BottomOptional;
				for (int i = foundConnCoord.x + 1; i < givenGrid.RowCount; i++)
				{
					givenGrid[i, foundConnCoord.y] = null;
				}
			}
			else if (item2.Value.connection == Tile.ConnectionType.RightOptional || item2.Value.connection == Tile.ConnectionType.RightRequired)
			{
				foundConnType = Tile.ConnectionType.RightOptional;
				for (int j = foundConnCoord.y + 1; j < givenGrid.ColCount; j++)
				{
					givenGrid[foundConnCoord.x, j] = null;
				}
			}
			else if (item2.Value.connection == Tile.ConnectionType.LeftOptional || item2.Value.connection == Tile.ConnectionType.LeftRequired)
			{
				foundConnType = Tile.ConnectionType.LeftOptional;
				for (int num2 = foundConnCoord.y - 1; num2 >= 0; num2--)
				{
					givenGrid[foundConnCoord.x, num2] = null;
				}
			}
			if (foundConnType == originConnType)
			{
				list.Add(foundConnCoord);
			}
		}
		IntVec2 intVec = ((givenDirection != MapDirections.North && givenDirection != MapDirections.South) ? new IntVec2(1) : new IntVec2(0, 1));
		int num3 = 4;
		for (int k = 0; k < list.Count; k++)
		{
			if (!list.Contains(list[k] - intVec))
			{
				givenConnectionList.Add(list[k]);
			}
		}
		for (int l = 0; l < givenConnectionList.Count; l++)
		{
			IntVec2 item = givenConnectionList[l] + intVec * num3;
			if (list.Contains(item))
			{
				givenConnectionList.Add(item);
			}
		}
		for (int m = 0; m < list.Count; m++)
		{
			if (!givenConnectionList.Contains(list[m]))
			{
				givenConnectionDict.Remove(list[m]);
			}
		}
	}

	public static int CanPlaceGrid(TileGrid givenRoomGrid, TileGrid givenMapGrid, IntVec2 givenStart)
	{
		placeRoomMax = new IntVec2(givenRoomGrid.RowCount, givenRoomGrid.ColCount);
		placeRoomState = 0;
		for (rowIter = 0; rowIter < placeRoomMax.x; rowIter++)
		{
			for (colIter = 0; colIter < placeRoomMax.y; colIter++)
			{
				tempTile = givenRoomGrid[rowIter, colIter];
				if (tempTile != null)
				{
					placeRoomState = Mathf.Max(placeRoomState, CanPlaceTile(givenStart.x + rowIter, givenStart.y + colIter, givenMapGrid, tempTile));
				}
				if (placeRoomState == 2)
				{
					return 2;
				}
			}
		}
		return placeRoomState;
	}

	private static int CanPlaceTile(int givenX, int givenY, TileGrid givenMapGrid, Tile givenCheckTile)
	{
		if (IsValidPosition(givenX, givenY))
		{
			if (givenMapGrid[givenX, givenY] == null)
			{
				return 0;
			}
			if (givenMapGrid[givenX, givenY].terrain == Tile.TerrainType.Impassable)
			{
				return 2;
			}
			if (givenMapGrid[givenX, givenY].roomStub == null)
			{
				Debug.Log("Existing tile room stub shouldn't be null.");
				return 2;
			}
			if (givenCheckTile.roomStub == null)
			{
				Debug.Log("Given tile room stub shouldn't be null.");
				return 2;
			}
			if (givenMapGrid[givenX, givenY].roomStub.type == RoomType.Hallway && givenCheckTile.roomStub.type == RoomType.Hallway)
			{
				return 1;
			}
		}
		return 2;
	}

	private static bool IsValidPosition(int givenX, int givenY)
	{
		return givenX >= 8 && givenX < LayoutGenerator.mapSizePadded.x && givenY >= 8 && givenY < LayoutGenerator.mapSizePadded.y;
	}
}
