public class Decorator
{
	internal List<Decoration> globalDecorations0;

	internal List<Decoration> globalDecorations1;

	internal List<Decoration> roomDecorations;

	private static Dictionary<string, Decorator> _tileSetDecorators;

	public static Dictionary<string, Decorator> TileSetDecorators
	{
		get
		{
			if (_tileSetDecorators == null)
			{
				_tileSetDecorators = new Dictionary<string, Decorator>();
				Decorator decorator = new Decorator();
				_tileSetDecorators["IceTileSet"] = new IceDecorator();
				_tileSetDecorators["EarthTileSet"] = new EarthDecorator();
				_tileSetDecorators["CastleBaseTileSet"] = new CastleBaseDecorator();
				_tileSetDecorators["HomeTileSet"] = new HomeDecorator();
				_tileSetDecorators["FireTileSet"] = new FireDecorator();
				_tileSetDecorators["MuseumTileSet"] = new MuseumDecorator();
				_tileSetDecorators["PlazaTileSet"] = new PlazaDecorator();
				_tileSetDecorators["AirTileSet"] = new AirDecorator();
				_tileSetDecorators["LightningTileSet"] = new LightningDecorator();
				_tileSetDecorators["FinalBossTileSet"] = new FinalBossDecorator();
			}
			return _tileSetDecorators;
		}
	}

	public Decorator()
	{
		globalDecorations0 = new List<Decoration>();
		globalDecorations1 = new List<Decoration>();
		roomDecorations = new List<Decoration>();
		InitDecorations();
		PrioritizeDecorations();
	}

	public virtual void InitDecorations()
	{
		globalDecorations1.Add(new LeftWallEdgeDecoration());
		globalDecorations1.Add(new RightWallEdgeDecoration());
	}

	public void PrioritizeDecorations()
	{
		globalDecorations0 = globalDecorations0.OrderByDescending((Decoration x) => x.priority).ToList();
		globalDecorations1 = globalDecorations1.OrderByDescending((Decoration x) => x.priority).ToList();
		roomDecorations = roomDecorations.OrderByDescending((Decoration x) => x.priority).ToList();
	}

	public static void DecorateByTileSet(string tileSetName, TileGrid tileGrid, DecorationMode mode = DecorationMode.Room, Room room = null, int pass = 0)
	{
		TileSetDecorators[tileSetName].Decorate(tileGrid, mode, room, pass);
	}

	public virtual void Decorate(TileGrid tileGrid, DecorationMode mode = DecorationMode.Room, Room room = null, int pass = 0)
	{
		List<Decoration> list = globalDecorations0;
		if (mode == DecorationMode.Room)
		{
			list = roomDecorations;
		}
		else if (pass == 1)
		{
			list = globalDecorations1;
		}
		Transform parentTrans = null;
		if (room != null)
		{
			parentTrans = room.InteractablesTrans;
		}
		else if (Level.levelContainer != null)
		{
			parentTrans = Level.levelContainer.transform;
		}
		for (int i = 0; i < list.Count; i++)
		{
			list[i].spawnPositions.Clear();
		}
		for (int j = 0; j < tileGrid.RowCount; j++)
		{
			for (int k = 0; k < tileGrid.ColCount; k++)
			{
				for (int l = 0; l < list.Count; l++)
				{
					if (list[l].Roll() && list[l].CanPlace(tileGrid, j, k, parentTrans, room))
					{
						list[l].Place(tileGrid, j, k, parentTrans, room);
					}
				}
			}
		}
	}
}
using System.Collections.Generic;
using UnityEngine;

public class WeightedRandomizer
{
	public List<WeightedItem> weightedItems;

	public Dictionary<string, WeightedItem> weightedItemsDict;

	public int weightedRange;

	public WeightedRandomizer()
	{
		weightedItems = new List<WeightedItem>();
		weightedItemsDict = new Dictionary<string, WeightedItem>();
	}

	public void Add(WeightedItem newItem)
	{
		weightedItems.Add(newItem);
		weightedItemsDict[newItem.name] = newItem;
		RecalculateWeights();
	}

	public void Remove(WeightedItem rmItem)
	{
		weightedItems.Remove(rmItem);
		weightedItemsDict.Remove(rmItem.name);
		RecalculateWeights();
	}

	public WeightedItem Get(string name)
	{
		return weightedItemsDict[name];
	}

	public void SetWeight(string name, int weight)
	{
		weightedItemsDict[name].weight = weight;
		RecalculateWeights();
	}

	public void Clear()
	{
		weightedItems.Clear();
		weightedItemsDict.Clear();
	}

	public void Print()
	{
		string text = string.Empty;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			string text2 = text;
			text = text2 + weightedItem.name + ": " + weightedItem.weight + "\n";
		}
		Debug.Log(text);
	}

	public void RecalculateWeights()
	{
		int num = 0;
		int num2 = 0;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			weightedItem.groupID = num;
			weightedItem.lowerBound = num2;
			num2 += weightedItem.weight;
			weightedItem.upperBound = num2 - 1;
			num++;
		}
		weightedRange = num2;
	}

	public WeightedItem GetRandomItem()
	{
		int num = Random.Range(0, weightedRange);
		int num2 = 0;
		foreach (WeightedItem weightedItem in weightedItems)
		{
			num2 = weightedItem.groupID;
			if (num <= weightedItem.upperBound)
			{
				return weightedItem;
			}
		}
		return null;
	}

	public int GetRandomGroupID()
	{
		return GetRandomItem()?.groupID ?? 0;
	}
}

