public static MapOrdinalDirections CheckAdjacentTiles(int tileRow, int tileCol, TileGrid tileGrid, Func<Tile, bool> comparisonFunc, bool cardinalOnly = false)
{
	int colCount = tileGrid.ColCount;
	int rowCount = tileGrid.RowCount;
	MapOrdinalDirections mapOrdinalDirections = MapOrdinalDirections.None;
	if (tileRow < rowCount - 1 && tileGrid[tileRow + 1, tileCol] != null && comparisonFunc(tileGrid[tileRow + 1, tileCol]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.South;
	}
	if (tileRow > 0 && tileGrid[tileRow - 1, tileCol] != null && comparisonFunc(tileGrid[tileRow - 1, tileCol]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.North;
	}
	if (tileCol > 0 && tileGrid[tileRow, tileCol - 1] != null && comparisonFunc(tileGrid[tileRow, tileCol - 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.West;
	}
	if (tileCol < colCount - 1 && tileGrid[tileRow, tileCol + 1] != null && comparisonFunc(tileGrid[tileRow, tileCol + 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.East;
	}
	if (cardinalOnly)
	{
		return mapOrdinalDirections;
	}
	if (tileRow < rowCount - 1 && tileCol > 0 && tileGrid[tileRow + 1, tileCol - 1] != null && comparisonFunc(tileGrid[tileRow + 1, tileCol - 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.SouthWest;
	}
	if (tileRow < rowCount - 1 && tileCol < colCount - 1 && tileGrid[tileRow + 1, tileCol + 1] != null && comparisonFunc(tileGrid[tileRow + 1, tileCol + 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.SouthEast;
	}
	if (tileRow > 0 && tileCol > 0 && tileGrid[tileRow - 1, tileCol - 1] != null && comparisonFunc(tileGrid[tileRow - 1, tileCol - 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.NorthWest;
	}
	if (tileRow > 0 && tileCol < colCount - 1 && tileGrid[tileRow - 1, tileCol + 1] != null && comparisonFunc(tileGrid[tileRow - 1, tileCol + 1]))
	{
		mapOrdinalDirections |= MapOrdinalDirections.NorthEast;
	}
	return mapOrdinalDirections;
}

