public virtual int PitToTileSetIDSubFunction(TileGrid tileGrid, int tileRow, int tileCol, int pitTilesAbove = 0, int pitTilesBelow = 0)
{
	if (pitTilesAbove == 0 && pitTilesBelow == 0)
	{
