	int i;
	for (i = tileRow; i < tileMap.GetLength(0) - 1 && tileMap[i + 1, tileCol] != null && tileMap[i + 1, tileCol].terrain == Tile.TerrainType.Pit; i++)
	{
		num2++;
	}
	i = tileRow;
	while (i > 0 && tileMap[i - 1, tileCol] != null && tileMap[i - 1, tileCol].terrain == Tile.TerrainType.Pit)
	{
		num++;
		i--;
	}
	if (num == 0 && num2 == 0)
	{
		return platformMidWallTiles.GetRandomValue();
	}
	return num switch
	{
		0 => platformTopWallTiles.GetRandomValue(), 
		1 => platformMidWallTiles.GetRandomValue(), 
		2 => platformLowerWallTiles.GetRandomValue(), 
		_ => pitTiles.GetRandomValue(), 
	};
}

