using System;
using System.Collections.Generic;
using UnityEngine;

[Serializable]
public class DropTableEntry
{
	public string name = "UndefinedDropTableEntry";

	public int minSoul;

	public int maxSoul;

	public float goldDropRate = 1f;

	public bool goldCompensation = true;

	public int minGold;

	public int maxGold;

	public float platDropRate;

	public int minPlat;

	public int maxPlat;

	public float lockedSkillDropRate;

	public float signatureSkillDropRate;

	public float skillDropRate;

	public int minSkill;

	public int maxSkill;

	public string[] skillDropList;

	public string[] skillElementList;

	private HashSet<ElementType> _skillElementSet;

	public float healthDropRate;

	public int minHealth;

	public int maxHealth;

	public float itemDropRate;

	public int minItem;

	public int maxItem;

	private int tempPlatAmt;

	private int tempSkillAmt;

	private int tempHealthAmt;

	private int tempItemAmt;

	private float tempPlatMult;

	private float tempGoldAmt;

	public string[] itemDropList;

	private List<string> CalcSkillDropList => new List<string>(skillDropList);

	public HashSet<ElementType> SkillElementSet
	{
		get
		{
			if (skillElementList == null || skillElementList.Length == 0)
			{
				return null;
			}
			if (_skillElementSet == null)
			{
				_skillElementSet = new HashSet<ElementType>();
				for (int i = 0; i < skillElementList.Length; i++)
				{
					_skillElementSet.Add(Globals.StrToElement(skillElementList[i]));
				}
			}
			return _skillElementSet;
		}
	}

	private List<string> CalcItemDropList => new List<string>(itemDropList);

	public int SoulAmount => UnityEngine.Random.Range(minSoul, maxSoul + 1);

	public int GoldAmount
	{
		get
		{
			tempGoldAmt = 0f;
			if (UnityEngine.Random.value < goldDropRate)
			{
				tempGoldAmt = (float)UnityEngine.Random.Range(minGold, maxGold + 1) * LootManager.globalGoldModifier.ModifiedValue;
				if (goldCompensation)
				{
					tempGoldAmt *= LootManager.GoldCompensationVal;
				}
				else
				{
					LootManager.nonCompensatedGoldVal += Mathf.CeilToInt(tempGoldAmt);
				}
			}
			return Mathf.CeilToInt(tempGoldAmt);
		}
	}

	public int PlatAmount
	{
		get
		{
			tempPlatAmt = minPlat;
			tempPlatMult = LootManager.PlatPerStageMultiplier;
			if (UnityEngine.Random.value < platDropRate)
			{
				tempPlatAmt = UnityEngine.Random.Range((minPlat <= 0) ? 1 : minPlat, maxPlat + 1);
			}
			if (tempPlatAmt > 1)
			{
				tempPlatAmt = Mathf.FloorToInt((float)tempPlatAmt * (1f + tempPlatMult));
			}
			else if (tempPlatAmt == 1)
			{
				tempPlatAmt += (int)LootManager.globalPlatModifier.CurrentValue + ((UnityEngine.Random.value < LootManager.PlatPerStageMultiplier) ? 1 : 0);
			}
			return tempPlatAmt;
		}
	}

	public int SkillAmount
	{
		get
		{
			tempSkillAmt = minSkill;
			for (int i = tempSkillAmt; i < maxSkill; i++)
			{
				if (UnityEngine.Random.value < skillDropRate)
				{
					tempSkillAmt++;
				}
			}
			return tempSkillAmt;
		}
	}

	public string SkillID
	{
		get
		{
			if (skillDropList != null && skillDropList.Length > 0)
			{
				List<string> calcSkillDropList = CalcSkillDropList;
				for (int num = calcSkillDropList.Count - 1; num >= 0; num--)
				{
					if (Player.AllPlayersHaveSkill(calcSkillDropList[num]) || !Player.SkillStateExists(calcSkillDropList[num]))
					{
						calcSkillDropList.RemoveAt(num);
					}
				}
				string result;
				if (calcSkillDropList.Count > 0)
				{
					result = calcSkillDropList[UnityEngine.Random.Range(0, calcSkillDropList.Count)];
				}
				else
				{
					result = ((SkillElementSet != null) ? string.Empty : LootManager.noDropID);
				}
				return result;
			}
			return string.Empty;
		}
	}

	public int HealthAmount
	{
		get
		{
			int num = minHealth;
			for (int i = num; i < maxHealth; i++)
			{
				if (UnityEngine.Random.value < healthDropRate * LootManager.HealthDropCompensationVal)
				{
					num++;
				}
			}
			return num;
		}
	}

	public int ItemAmount
	{
		get
		{
			tempItemAmt = minItem;
			for (int i = tempItemAmt; i < maxItem; i++)
			{
				if (UnityEngine.Random.value < itemDropRate)
				{
					tempItemAmt++;
				}
			}
			tempItemAmt = (int)((float)tempItemAmt * LootManager.itemDropModifier.CurrentValue);
			return tempItemAmt;
		}
	}

	public string ItemID
	{
		get
		{
			if (itemDropList != null && itemDropList.Length > 0)
			{
				List<string> calcItemDropList = CalcItemDropList;
				for (int num = calcItemDropList.Count - 1; num >= 0; num--)
				{
					if (Inventory.EitherPlayerHasItem(calcItemDropList[num]))
					{
						calcItemDropList.RemoveAt(num);
					}
				}
				return (calcItemDropList.Count <= 0) ? LootManager.noDropID : calcItemDropList[UnityEngine.Random.Range(0, calcItemDropList.Count)];
			}
			return string.Empty;
		}
	}

	public void SetMaxValues()
	{
		if (maxSoul == 0 && minSoul > 0)
		{
			maxSoul = minSoul;
		}
		if (maxGold == 0 && minGold > 0)
		{
			maxGold = minGold;
		}
		if (maxPlat == 0)
		{
			if (platDropRate > 0f && minPlat == 0)
			{
				maxPlat = 1;
			}
			else
			{
				maxPlat = minPlat;
			}
		}
		if (maxSkill == 0)
		{
			if (skillDropRate > 0f && minSkill == 0)
			{
				maxSkill = 1;
			}
			else
			{
				maxSkill = minSkill;
			}
		}
		if (maxHealth == 0)
		{
			if (healthDropRate > 0f && minHealth == 0)
			{
				maxHealth = 1;
			}
			else
			{
				maxHealth = minHealth;
			}
		}
		if (maxItem == 0)
		{
			if (itemDropRate > 0f && minItem == 0)
			{
				maxItem = 1;
			}
			else
			{
				maxItem = minItem;
			}
		}
	}

	public override string ToString()
	{
		string text = string.Empty;
		if (skillDropList != null)
		{
			text += "[";
			for (int i = 0; i < skillDropList.Length; i++)
			{
				text = text + skillDropList[i] + ",";
			}
			text += "]";
		}
		string text2 = string.Empty;
		if (skillElementList != null)
		{
			text2 += "[";
			for (int j = 0; j < skillElementList.Length; j++)
			{
				text2 = text2 + skillElementList[j] + ",";
			}
			text2 += "]";
		}
		string text3 = string.Empty;
		if (itemDropList != null)
		{
			text3 += "[";
			for (int k = 0; k < itemDropList.Length; k++)
			{
				text3 = text3 + itemDropList[k] + ",";
			}
			text3 += "]";
		}
		return "name: " + name + "\nhealthDropRate: " + healthDropRate + "\nminHealth: " + minHealth + "\nmaxHealth: " + maxHealth + "\nitemDropRate: " + itemDropRate + "\nminItem: " + minItem + "\nmaxItem: " + maxItem + "\nminSoul: " + minSoul + "\nmaxSoul: " + maxSoul + "\ngoldDropRate: " + goldDropRate + "\ngoldCompensation: " + goldCompensation + "\nminGold: " + minGold + "\nmaxGold: " + maxGold + "\nplatDropRate: " + platDropRate + "\nminPlat: " + minPlat + "\nmaxPlat: " + maxPlat + "\nlockedSkillDropRate: " + lockedSkillDropRate + "\nsignatureSkillDropRate: " + signatureSkillDropRate + "\nskillDropRate: " + skillDropRate + "\nminSkill: " + minSkill + "\nmaxSkill: " + maxSkill + "\nskillElementList: " + text2 + "\nskillDropList: " + text + "\nitemDropList: " + text3 + "\n";
	}
}
