using System.Collections.Generic;
using UnityEngine;

public class ItemStoreItem : StoreItem
{
	public delegate void SpawnEventHandler(ItemStoreItem item);

	private const int CursedPlatCost = 25;

	private const float CombinedItemChance = 0.03f;

	private static GameObject prefab;

	public static SpawnEventHandler spawnEventHandlers;

	private static string lastUsedCursedHubItemID = string.Empty;

	private string itemID = string.Empty;

	public static bool mimiSpawned;

	public static bool audioPlayed;

	private static bool brdtSpawned;

	private static List<string> currentItemIDs = new List<string>();

	public static List<ItemStoreItem> currentItems = new List<ItemStoreItem>();

	public static List<ItemStoreItem> cursedItems = new List<ItemStoreItem>();

	public bool disableMarkerOffset;

	public bool cursedOnly;

	public Light lightAux;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Items/ItemStoreItem.prefab"));

	public string ID => itemID;

	public static void ResetSpawnedItems()
	{
		currentItemIDs.Clear();
		currentItems.Clear();
		cursedItems.Clear();
		mimiSpawned = false;
		audioPlayed = false;
		brdtSpawned = false;
	}

	public override void Start()
	{
		base.Start();
		if (descText != null && canvasBG != null)
		{
			canvasBG.transform.localScale = new Vector3(descText.transform.localScale.x * 1.12f, canvasBG.transform.localScale.y, 1f);
		}
		transform.Find("ItemShadow").GetComponent<SortSpriteLayer>().yValueOffset = transform.GetComponent<SortSpriteLayer>().yValueOffset;
		if (usePlatinumCost)
		{
			if (cursedOnly)
			{
				if (HubEventHandler.cursePurchased)
				{
					if (priceMarker != null)
					{
						priceMarker.SetText("x");
					}
					Object.Destroy(gameObject);
					return;
				}
				if (lastUsedCursedHubItemID != string.Empty)
				{
					itemID = lastUsedCursedHubItemID;
					lastUsedCursedHubItemID = string.Empty;
					LootManager.RemoveIDFromAvailableList(itemID);
				}
				else
				{
					itemID = LootManager.GetAvailableItemID(1f, hubOnly: true);
				}
				PoolManager.GetPoolItem<CursedAura>("CursedAura").Play(gameObject, new Vector3(0f, -0.25f, 0f));
				EnableCursedLight();
				cursedItems.Add(this);
			}
			else
			{
				itemID = LootManager.GetLockedItemID();
				if (currentItemIDs.Contains(itemID))
				{
					itemID = string.Empty;
				}
			}
		}
		else if (cursedOnly)
		{
			if (Level.isBossRushMode && !brdtSpawned && GameController.tierCount == 0 && GameController.stageCount == 1)
			{
				brdtSpawned = true;
				itemID = DoubleTrouble.staticID;
				LootManager.RemoveIDFromAvailableList(itemID);
			}
			else
			{
				itemID = GetCombinedID(findCursed: true);
			}
			if (itemID == string.Empty)
			{
				itemID = LootManager.GetAvailableItemID(1f);
			}
			PoolManager.GetPoolItem<CursedAura>("CursedAura").Play(gameObject, new Vector3(0f, -0.25f, 0f));
			EnableCursedLight();
			cursedItems.Add(this);
		}
		else
		{
			itemID = GetCombinedID();
			if (itemID == string.Empty)
			{
				itemID = LootManager.GetAvailableItemID();
			}
		}
		if (!usePlatinumCost && !cursedOnly && !disableMarkerOffset)
		{
			priceMarker.OffsetSortValue(priceMarkerYOffset);
		}
		if (itemID == string.Empty)
		{
			CurrentOverheadPrompt = null;
			priceMarker.SetText("x");
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
			return;
		}
		itemSpriteRenderer.sprite = IconManager.GetItemIcon(itemID);
		itemText.text = TextManager.GetItemName(itemID);
		if (descText != null)
		{
			descText.text = TextManager.GetItemDescription(itemID);
		}
		overheadPromptHeight = 1f;
		if (usePlatinumCost)
		{
			costStat.Initialize((!cursedOnly) ? Mathf.Max(10, LootManager.GetPlatPrice(itemID)) : 25);
			topText.text = string.Empty;
		}
		else
		{
			costStat.Initialize(LootManager.GetPrice(itemID));
			isOnSale = !cursedOnly && Random.value < saleChance;
			if (isOnSale)
			{
				costStat.AddMod(StoreItem.SaleMod);
				topText.color = saleColor;
				topText.text = TextManager.GetUIText("storeItem-sale");
			}
			else
			{
				topText.text = string.Empty;
			}
		}
		if (cursedOnly && Cost == 0)
		{
			priceMarker.gameObject.SetActive(value: false);
		}
		priceMarker.SetText(Cost.ToString());
		currentItems.Add(this);
		currentItemIDs.Add(itemID);
		AnnounceSpawnEvent();
	}

	public void PlayDenyBuyEffects()
	{
		SoundManager.PlayAudio("MenuError");
		if (parentNpc != null)
		{
			parentNpc.PlayEmote(EmoteType.No);
		}
	}

	private void CurseBuyEvent(bool inRun = true)
	{
		SoundManager.PlayAudio("CursedMerchant0");
		if (inRun)
		{
			RunData.miscCursedStoreFound = true;
		}
		else
		{
			HubEventHandler.cursePurchased = true;
			lastUsedCursedHubItemID = itemID;
		}
		foreach (ItemStoreItem cursedItem in cursedItems)
		{
			if (cursedItem != null && cursedItem.transform != null && cursedItem != this && cursedItem.gameObject != null)
			{
				if (cursedItem.priceMarker != null)
				{
					cursedItem.priceMarker.SetText("x");
				}
				Object.Destroy(cursedItem.gameObject);
			}
		}
	}

	private bool BuyWithPlat()
	{
		if (Player.platWallet.balance < Cost)
		{
			SoundManager.PlayAudio("MenuError");
			if (parentNpc != null)
			{
				parentNpc.PlayEmote(EmoteType.No);
			}
			return false;
		}
		Player.platWallet.Withdraw(Cost);
		SoundManager.PlayAudio("MenuBuy");
		CurrentOverheadPrompt = null;
		priceMarker.SetText("x");
		return true;
	}

	public override bool Buy(Player player)
	{
		if (usePlatinumCost && cursedOnly)
		{
			if (player.inventory.ContainsItem(itemID) || player.inventory.IsFull)
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (!BuyWithPlat())
			{
				return false;
			}
			if (!player.inventory.AddItem(Item.CreateItem(itemID), showNotice: true))
			{
				PlayDenyBuyEffects();
				return false;
			}
			CurseBuyEvent(inRun: false);
		}
		else if (usePlatinumCost)
		{
			if (!BuyWithPlat())
			{
				return false;
			}
			Item.IsUnlocked(itemID, setUnlocked: true);
			GameController.unlockNotifier.Notify(itemID, UnlockNotifier.NoticeType.Relic);
			Player.newItems[LootManager.completeItemDict[itemID].category].Add(itemID);
			if (!mimiSpawned)
			{
				mimiSpawned = true;
				SpawnMimi();
			}
		}
		else
		{
			if (player.inventory.CursedCount >= 12)
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (player.inventory.ContainsItem(itemID) || !base.Buy(player) || !player.inventory.AddItem(Item.CreateItem(itemID), showNotice: true))
			{
				PlayDenyBuyEffects();
				return false;
			}
			if (cursedOnly)
			{
				CurseBuyEvent();
			}
			else
			{
				RunData.reqItemStoreFound = true;
			}
		}
		if (!cursedOnly && !audioPlayed)
		{
			audioPlayed = true;
			SoundManager.PlayAudio((!Globals.RandBool) ? "Artisan1" : "Artisan0");
		}
		if ((usePlatinumCost && !cursedOnly) || itemID == StoreRestock.staticID)
		{
			ItemStoreItem itemStoreItem = Globals.ChaosInst<ItemStoreItem>(Prefab, transform.parent, transform.position);
			itemStoreItem.usePlatinumCost = usePlatinumCost;
			itemStoreItem.cursedOnly = cursedOnly;
			itemStoreItem.priceMarkerYOffset = priceMarkerYOffset;
			if (transform.GetComponent<SortSpriteLayer>() != null)
			{
				itemStoreItem.GetComponent<SortSpriteLayer>().yValueOffset = transform.GetComponent<SortSpriteLayer>().yValueOffset;
			}
			itemStoreItem.parentNpc = parentNpc;
			if (priceMarker != null && priceMarker.gameObject != null)
			{
				Object.Destroy(priceMarker.gameObject);
			}
		}
		if (parentNpc != null)
		{
			parentNpc.PlayDefaultEmote();
		}
		if (gameObject != null)
		{
			Object.Destroy(gameObject);
		}
		return true;
	}

	public void EnableCursedLight()
	{
		if (!(lightAux == null))
		{
			lightAux.enabled = true;
			lightAux.color = new Color32(92, 0, 0, byte.MaxValue);
			lightAux.intensity = 4f;
			lightAux.range = 3f;
			lightAux.transform.position = new Vector3(lightAux.transform.position.x, lightAux.transform.position.y, -0.5f);
		}
	}

	public void AnnounceSpawnEvent()
	{
		if (spawnEventHandlers != null)
		{
			spawnEventHandlers(this);
		}
	}

	public string GetCombinedID(bool findCursed = false)
	{
		if (Random.value > 0.03f)
		{
			return string.Empty;
		}
		string empty = string.Empty;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player == null || player.inventory == null)
			{
				continue;
			}
			foreach (Item value in player.inventory.itemDict.Values)
			{
				if (value != null && value.parentCombineID != string.Empty)
				{
					empty = ItemRecipe.GetMissingRecipeItem(value.ID, findCursed);
					if (!currentItemIDs.Contains(empty) && findCursed == Item.IsCursedItem(empty))
					{
						LootManager.RemoveIDFromAvailableList(empty);
						return empty;
					}
					empty = string.Empty;
				}
			}
		}
		return string.Empty;
	}

	public static void SpawnMimi()
	{
		Vector2 vector = new Vector2(-14f, 8f);
		PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(vector, string.Empty);
		Globals.ChaosInst<MimicNpc>(MimicNpc.Prefab, null, vector);
		Attack attack = Globals.ChaosInst<Attack>(Attack.CirclePrefab, null, vector);
		attack.SetAttackInfo("Player", Player.ShootFireball.staticID);
		attack.transform.localScale = Vector3.one * 4f;
		Object.Destroy(attack.gameObject, 0.25f);
	}
}
using System.Collections.Generic;
using UnityEngine;

public class SkillStoreItem : StoreItem
{
	public delegate void SpawnEventHandler(SkillStoreItem item);

	private static GameObject prefab;

	public static SpawnEventHandler spawnEventHandlers;

	private bool initialized;

	private static int signatureCost = 50;

	private static int empoweredBaseCost = 100;

	private static int empoweredCostIncrease = 50;

	private static float ownedEmpowerChance = 0.45f;

	private bool isOwnedEmpowered;

	public static int empoweredBuyCount = 0;

	private static int chaosLoopReq = 1;

	private static float chaosChance = 0.35f;

	private static float winItemChance = 0.75f;

	private bool isChaosSpell;

	public static bool tomiSpawned;

	private static List<string> currentSkillIDs = new List<string>();

	public static List<SkillStoreItem> currentSkills = new List<SkillStoreItem>();

	private bool lockedSkillSelected;

	private Color newSkillColor = new Color(0f, 0.72f, 1f);

	public float rollRadius;

	private bool inRange;

	public string skillID = string.Empty;

	public bool signatureOnly;

	public bool isEmpowered;

	public bool ignoreEmpoweredReqs;

	public bool isShufflerItem;

	private static bool shufflerHasChaos = false;

	public SpriteRenderer standardSR;

	public SpriteRenderer empoweredSR;

	public SpriteRenderer sigSR;

	public static bool audioPlayed;

	private List<string> empIDList = new List<string>();

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Items/SkillStoreItem.prefab"));

	public static void ResetSpawnedSkills()
	{
		currentSkillIDs.Clear();
		currentSkills.Clear();
		tomiSpawned = false;
		audioPlayed = false;
		shufflerHasChaos = false;
	}

	public override void Start()
	{
		base.Start();
		if (descText != null && canvasBG != null)
		{
			canvasBG.transform.localScale = new Vector3(descText.transform.localScale.x * 1.12f, canvasBG.transform.localScale.y, 1f);
		}
	}

	public override void Update()
	{
		base.Update();
		if (initialized)
		{
			return;
		}
		if (!inRange)
		{
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (rollRadius >= Vector2.Distance(transform.position, player.transform.position))
				{
					inRange = true;
					break;
				}
			}
			return;
		}
		if (skillID != string.Empty)
		{
			Initialize();
			return;
		}
		if (usePlatinumCost && SetSkillIDFromList(locked: true))
		{
			lockedSkillSelected = true;
		}
		if (!lockedSkillSelected && SetSkillIDFromList())
		{
			isOnSale = Random.value < saleChance;
		}
		if (skillID != string.Empty)
		{
			Initialize();
			return;
		}
		priceMarker.SetText("x");
		Object.Destroy(gameObject);
	}

	private bool SetSkillIDFromList(bool locked = false)
	{
		if (isShufflerItem)
		{
			ignoreEmpoweredReqs = shufflerHasChaos;
		}
		if (isEmpowered && !ignoreEmpoweredReqs)
		{
			empIDList.Clear();
			if ((Inventory.EitherPlayerHasItem(PlayerWinItem.staticID) && Random.value < winItemChance) || (GameController.loopCount >= chaosLoopReq && Random.value < chaosChance))
			{
				empIDList = new List<string>(LootManager.chaosSkillList);
				for (int num = empIDList.Count - 1; num >= 0; num--)
				{
					if (!GameDataManager.gameData.CheckSkillDataEntry(empIDList[num]) || currentSkillIDs.Contains(empIDList[num]))
					{
						empIDList.RemoveAt(num);
					}
				}
				Player[] activePlayers = GameController.activePlayers;
				foreach (Player player in activePlayers)
				{
					if (player == null || player.assignedSkills == null)
					{
						continue;
					}
					Player.SkillState[] assignedSkills = player.assignedSkills;
					foreach (Player.SkillState skillState in assignedSkills)
					{
						if (skillState != null)
						{
							empIDList.Remove(skillState.skillID);
						}
					}
					if (player.stockSkill != null)
					{
						empIDList.Remove(player.stockSkill.skillID);
					}
				}
				if (empIDList.Count > 0)
				{
					isChaosSpell = true;
					skillID = empIDList[Random.Range(0, empIDList.Count)];
					if (isShufflerItem)
					{
						shufflerHasChaos = true;
					}
				}
			}
			if (!isChaosSpell && !isShufflerItem && Random.value < ownedEmpowerChance)
			{
				Player[] activePlayers2 = GameController.activePlayers;
				foreach (Player player2 in activePlayers2)
				{
					if (player2 == null || player2.assignedSkills == null)
					{
						continue;
					}
					Player.SkillState[] assignedSkills2 = player2.assignedSkills;
					foreach (Player.SkillState skillState2 in assignedSkills2)
					{
						if (skillState2 != null && !skillState2.IsEmpowered && !currentSkillIDs.Contains(skillState2.skillID))
						{
							empIDList.Add(skillState2.skillID);
						}
					}
					if (player2.stockSkill != null && !player2.stockSkill.IsEmpowered && !currentSkillIDs.Contains(player2.stockSkill.skillID))
					{
						empIDList.Add(player2.stockSkill.skillID);
					}
				}
				if (empIDList.Count > 0)
				{
					isOwnedEmpowered = true;
					skillID = empIDList[Random.Range(0, empIDList.Count)];
				}
			}
		}
		if (skillID == string.Empty)
		{
			skillID = LootManager.GetSkillID(locked, signatureOnly);
		}
		if (signatureOnly && skillID == string.Empty)
		{
			signatureOnly = false;
			skillID = LootManager.GetSkillID(locked: true);
		}
		if (skillID != string.Empty)
		{
			currentSkillIDs.Add(skillID);
			return true;
		}
		return false;
	}

	public override bool Buy(Player player)
	{
		if (usePlatinumCost)
		{
			if (Player.platWallet.balance < Cost)
			{
				SoundManager.PlayAudio("MenuError");
				if (parentNpc != null)
				{
					parentNpc.PlayEmote(EmoteType.No);
				}
				return false;
			}
			Player.platWallet.Withdraw(Cost);
			SoundManager.PlayAudio("MenuBuy");
			CurrentOverheadPrompt = null;
			priceMarker.SetText("x");
			player.HandleSkillUnlock(skillID, signatureOnly);
			if (!tomiSpawned)
			{
				tomiSpawned = true;
				SpawnTomi();
			}
			SkillStoreItem skillStoreItem = Globals.ChaosInst<SkillStoreItem>(Prefab, transform.parent, transform.position);

			SkillStoreItem skillStoreItem = Globals.ChaosInst<SkillStoreItem>(Prefab, transform.parent, transform.position);
			skillStoreItem.usePlatinumCost = true;
			skillStoreItem.signatureOnly = signatureOnly;
			skillStoreItem.parentNpc = parentNpc;
			Object.Destroy(priceMarker.gameObject);
		}
		else
		{
			if (!base.Buy(player))
			{
				return false;
			}
			string givenID = skillID;
			bool flag = isEmpowered;
			player.PickUpSkill(givenID, isSignature: false, flag);
			RunData.reqSkillStoreFound = true;
		}
		if (!audioPlayed && !disablePriceMarker)
		{
			audioPlayed = true;
			SoundManager.PlayAudio("Virtuoso0");
		}
		if (parentNpc != null)
		{
			parentNpc.PlayDefaultEmote();
		}
		Object.Destroy(gameObject);
		return true;
	}

	public void Initialize()
	{
		if (skillID == string.Empty)
		{
			return;
		}
		itemSpriteRenderer.sprite = IconManager.GetSkillIcon(skillID);
		itemText.text = TextManager.GetSkillName(skillID);
		descText.text = TextManager.GetSkillDescription(skillID, empowered: false, isChaos: true);
		overheadPromptHeight = 2.5f;
		if (isEmpowered)
		{
			if (isChaosSpell)
			{
				costStat.Initialize(LootManager.GetPrice(skillID));
			}
			else if (isOwnedEmpowered)
			{
				costStat.Initialize(empoweredBaseCost);
			}
			else
			{
				costStat.Initialize(LootManager.GetPrice(skillID) + empoweredCostIncrease);
			}
			topText.text = string.Empty;
			topText.color = newSkillColor;
		}
		else if (isOnSale)
		{
			costStat.Initialize(LootManager.GetPrice(skillID));
			costStat.AddMod(StoreItem.SaleMod);
			topText.text = TextManager.GetUIText("storeItem-sale");
			topText.color = saleColor;
		}
		else
		{
			costStat.Initialize(LootManager.GetPrice(skillID));
			topText.text = string.Empty;
		}
		if (usePlatinumCost)
		{
			costStat.Initialize((!signatureOnly) ? Mathf.Max(10, LootManager.GetPlatPrice(skillID, isItem: false)) : signatureCost);
			if (!lockedSkillSelected)
			{
				CurrentOverheadPrompt = null;
				priceMarker.SetText("x");
				Object.Destroy(gameObject);
				return;
			}
		}
		SetCardSprite();
		priceMarker.SetText(Cost.ToString());
		initialized = true;
		currentSkills.Add(this);
		AnnounceSpawnEvent();
	}

	private void SetCardSprite()
	{
		if (signatureOnly)
		{
			sigSR.enabled = true;
		}
		else if (isEmpowered)
		{
			empoweredSR.enabled = true;
		}
		else
		{
			standardSR.enabled = true;
